options(stringsAsFactors=FALSE)
suppressPackageStartupMessages({library(data.table);library(edgeR);library(survival);library(glmnet);library(ranger);library(httr);library(jsonlite)})
root <- "D:/PDAC_P1"; out <- file.path(root,"analysis/14_prediction/epas1_survival_ml"); dir.create(out,recursive=TRUE,showWarnings=FALSE)
study.tcga <- "paad_tcga_pan_can_atlas_2018"; study.cptac <- "paad_cptac_2021"
get.clin <- function(study) { x<-fromJSON(content(GET(paste0("https://www.cbioportal.org/api/studies/",study,"/clinical-data?clinicalDataType=PATIENT&projection=DETAILED")),as="text",encoding="UTF-8")); dcast(as.data.table(x)[,.(patientId,clinicalAttributeId,value)],patientId~clinicalAttributeId,value.var="value") }
get.sample.clin <- function(study) { x<-fromJSON(content(GET(paste0("https://www.cbioportal.org/api/studies/",study,"/clinical-data?clinicalDataType=SAMPLE&projection=DETAILED")),as="text",encoding="UTF-8")); dcast(as.data.table(x)[,.(sampleId,clinicalAttributeId,value)],sampleId~clinicalAttributeId,value.var="value") }
stage.bin <- function(x) as.integer(grepl("III|IV",toupper(as.character(x))))
z <- function(x) as.numeric(scale(x))
score.signed <- function(mat,up,down) { # genes x samples
  up<-intersect(up,rownames(mat)); down<-intersect(down,rownames(mat)); zz<-t(scale(t(mat))); a<-if(length(up))colMeans(zz[up,,drop=FALSE])else rep(0,ncol(mat)); b<-if(length(down))colMeans(zz[down,,drop=FALSE])else rep(0,ncol(mat));(a-b)/(as.integer(length(up)>0)+as.integer(length(down)>0))
}
cand <- fread(file.path(root,"analysis/07_candidate_screen/candidate_genes_stable_high_confidence_all.tsv"))
up <- cand[major_lineage=="endothelial"&stable_high_confidence==TRUE&direction=="tumor_up",gene_id]; down <- cand[major_lineage=="endothelial"&stable_high_confidence==TRUE&direction=="tumor_down",gene_id]
allg <- unique(c(up,down,"EPAS1","PECAM1","VWF","EMCN"))

# TCGA molecular features from original count matrix.
cts <- readRDS(file.path(root,"analysis/01_tcga_qc/TCGA-PAAD_primary_tumor_counts_unstranded.rds")); ann <- readRDS(file.path(root,"analysis/01_tcga_qc/TCGA-PAAD_gene_annotation.rds")); sy<-ann$gene_name[match(rownames(cts),ann$gene_id)]; keep<-!is.na(sy)&sy!=""; cts<-cts[keep,,drop=FALSE]; rownames(cts)<-make.unique(sy[keep]); tx<-cpm(DGEList(counts=cts),log=TRUE,prior.count=2)
tcga.mol <- data.table(patientId=substr(colnames(tx),1,12),EPAS1=z(as.numeric(tx["EPAS1",])),endo=z(score.signed(tx,setdiff(up,"EPAS1"),down)))
tcga.cl <- get.clin(study.tcga); tcga.cl[,time:=as.numeric(OS_MONTHS)*30.4375];tcga.cl[,event:=as.integer(grepl("DECEASED",toupper(OS_STATUS)))];tcga.cl[,age10:=as.numeric(AGE)/10];tcga.cl[,advanced:=stage.bin(AJCC_PATHOLOGIC_TUMOR_STAGE)]
train <- merge(tcga.mol,tcga.cl[,.(patientId,time,event,age10,advanced)],by="patientId"); train<-train[is.finite(time)&time>0&!is.na(event)&is.finite(age10)&!is.na(advanced)]

# CPTAC mRNA fetched for the same pre-specified genes, then cohort-wise molecular standardization only.
gid <- sapply(allg,function(g){rr<-GET(paste0("https://www.cbioportal.org/api/genes/",URLencode(g,reserved=TRUE)));if(status_code(rr)==200)fromJSON(content(rr,as="text"))$entrezGeneId else NA_integer_}); gid<-gid[!is.na(gid)]
samp <- fromJSON(content(GET(paste0("https://www.cbioportal.org/api/studies/",study.cptac,"/samples?projection=SUMMARY")),as="text")); body<-list(entrezGeneIds=as.integer(gid),sampleIds=as.character(samp$sampleId)); rr<-POST(paste0("https://www.cbioportal.org/api/molecular-profiles/",study.cptac,"_mrna/molecular-data/fetch"),body=body,encode="json");stop_for_status(rr); md<-as.data.table(fromJSON(content(rr,as="text"))); id2g<-setNames(names(gid),as.character(gid)); md[,gene:=id2g[as.character(entrezGeneId)]]; mm<-dcast(md,gene~sampleId,value.var="value",fun.aggregate=median); rn<-mm$gene; mm<-as.matrix(mm[,-1]);rownames(mm)<-rn
cpt.mol <- data.table(patientId=colnames(mm),EPAS1=z(as.numeric(mm["EPAS1",])),endo=z(score.signed(mm,setdiff(up,"EPAS1"),down)))
cpt.cl <- get.clin(study.cptac); cpt.stage <- get.sample.clin(study.cptac)[,.(patientId=sampleId,TUMOR_STAGE_PATHOLOGICAL)]; cpt.cl <- merge(cpt.cl,cpt.stage,by="patientId",all.x=TRUE); cpt.cl[,time:=as.numeric(FOLLOW_UP_DAYS)];cpt.cl[,event:=as.integer(tolower(VITAL_STATUS)=="deceased")];cpt.cl[,age10:=as.numeric(AGE)/10];cpt.cl[,advanced:=stage.bin(TUMOR_STAGE_PATHOLOGICAL)]
test <- merge(cpt.mol,cpt.cl[,.(patientId,time,event,age10,advanced)],by="patientId"); test<-test[is.finite(time)&time>0&!is.na(event)&is.finite(age10)&!is.na(advanced)]
fwrite(train,file.path(out,"TCGA_survival_model_input.tsv"),sep="\t");fwrite(test,file.path(out,"CPTAC_survival_model_input.tsv"),sep="\t")
features <- c("EPAS1","endo","age10","advanced")
ci <- function(d,lp) as.numeric(concordance(Surv(d$time,d$event)~lp)$concordance)
set.seed(20260903); folds<-sample(rep(1:5,length.out=nrow(train))); oof<-data.table(row=seq_len(nrow(train)),fold=folds,clinical=NA_real_,molecular_cox=NA_real_,elastic_net=NA_real_,survival_forest=NA_real_)
for(k in 1:5){tr<-train[folds!=k];va<-train[folds==k]; f1<-coxph(Surv(time,event)~age10+advanced,data=tr,x=TRUE);f2<-coxph(Surv(time,event)~EPAS1+endo+age10+advanced,data=tr,x=TRUE); x<-as.matrix(tr[,..features]); en<-cv.glmnet(x,Surv(tr$time,tr$event),family="cox",nfolds=5); rf<-ranger(Surv(time,event)~EPAS1+endo+age10+advanced,data=as.data.frame(tr),num.trees=1000,min.node.size=10,seed=20260903+k,importance="permutation"); rf.pred<-rowSums(predict(rf,va)$chf);oof[fold==k,`:=`(clinical=predict(f1,va,type="lp"),molecular_cox=predict(f2,va,type="lp"),elastic_net=as.numeric(predict(en,newx=as.matrix(va[,..features]),s="lambda.1se",type="link")),survival_forest=rf.pred)]}
f1<-coxph(Surv(time,event)~age10+advanced,data=train,x=TRUE);f2<-coxph(Surv(time,event)~EPAS1+endo+age10+advanced,data=train,x=TRUE);en<-cv.glmnet(as.matrix(train[,..features]),Surv(train$time,train$event),family="cox",nfolds=10);rf<-ranger(Surv(time,event)~EPAS1+endo+age10+advanced,data=as.data.frame(train),num.trees=2000,min.node.size=10,seed=20260903,importance="permutation")
external <- data.table(patientId=test$patientId,clinical=predict(f1,test,type="lp"),molecular_cox=predict(f2,test,type="lp"),elastic_net=as.numeric(predict(en,newx=as.matrix(test[,..features]),s="lambda.1se",type="link")),survival_forest=rowSums(predict(rf,test)$chf))
mods<-c("clinical","molecular_cox","elastic_net","survival_forest"); perf<-rbindlist(lapply(mods,function(m)data.table(model=m,TCGA_5fold_Cindex=ci(train,oof[[m]]),CPTAC_external_Cindex=ci(test,external[[m]]))))
fwrite(oof,file.path(out,"TCGA_5fold_predictions.tsv"),sep="\t");fwrite(external,file.path(out,"CPTAC_external_predictions.tsv"),sep="\t");fwrite(perf,file.path(out,"survival_model_performance.tsv"),sep="\t");fwrite(data.table(feature=rownames(as.matrix(coef(en,s="lambda.1se"))),coefficient=as.numeric(coef(en,s="lambda.1se"))),file.path(out,"elastic_net_coefficients.tsv"),sep="\t");fwrite(data.table(feature=names(rf$variable.importance),permutation_importance=as.numeric(rf$variable.importance)),file.path(out,"survival_forest_importance.tsv"),sep="\t")
writeLines(c("# EPAS1-centered survival ML audit","",paste0("- TCGA training n=",nrow(train),", events=",sum(train$event),"; CPTAC external n=",nrow(test),", events=",sum(test$event),"."),"- Molecular features were fixed before fitting: EPAS1 expression and endothelial score excluding EPAS1. Clinical features were age and stage III/IV.","- Models: clinical Cox, molecular+clinical Cox, elastic-net Cox and survival forest sensitivity analysis.","- Cohort-wise z-standardization is applied to molecular variables to mitigate measurement-platform scale differences; this means the model is a relative molecular-state model, not an absolute assay-ready score.","- Report only methods whose CPTAC external C-index is at least comparable to the clinical Cox baseline; do not select the maximum internal C-index."),file.path(out,"survival_ml_report.md"))
